changeSet.sql:
INSERT INTO m_role_permission (role_id, permission_id) SELECT rp.role_id, new_p.id FROM m_role_permission rp JOIN m_permission old_p ON old_p.id = rp.permission_id AND old_p.code = 'DEPOSIT_SAVINGSACCOUNT' JOIN m_permission new_p ON new_p.code = 'GLTOSAVINGS_SAVINGSACCOUNT' WHERE NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = new_p.id );
INSERT INTO m_role_permission (role_id, permission_id) SELECT rp.role_id, new_p.id FROM m_role_permission rp JOIN m_permission old_p ON old_p.id = rp.permission_id AND old_p.code = 'DEPOSIT_SAVINGSACCOUNT_CHECKER' JOIN m_permission new_p ON new_p.code = 'GLTOSAVINGS_SAVINGSACCOUNT_CHECKER' WHERE NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = new_p.id );
INSERT INTO m_role_permission (role_id, permission_id) SELECT rp.role_id, new_p.id FROM m_role_permission rp JOIN m_permission old_p ON old_p.id = rp.permission_id AND old_p.code = 'WITHDRAWAL_SAVINGSACCOUNT' JOIN m_permission new_p ON new_p.code = 'SAVINGSTOGL_SAVINGSACCOUNT' WHERE NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = new_p.id );
INSERT INTO m_role_permission (role_id, permission_id) SELECT rp.role_id, new_p.id FROM m_role_permission rp JOIN m_permission old_p ON old_p.id = rp.permission_id AND old_p.code = 'WITHDRAWAL_SAVINGSACCOUNT_CHECKER' JOIN m_permission new_p ON new_p.code = 'SAVINGSTOGL_SAVINGSACCOUNT_CHECKER' WHERE NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = new_p.id );
INSERT INTO m_role_permission (role_id, permission_id) SELECT 1, p.id FROM m_permission p WHERE p.code IN ('GLTOSAVINGS_SAVINGSACCOUNT', 'GLTOSAVINGS_SAVINGSACCOUNT_CHECKER', 'SAVINGSTOGL_SAVINGSACCOUNT', 'SAVINGSTOGL_SAVINGSACCOUNT_CHECKER') AND NOT EXISTS (SELECT 1 FROM m_role_permission rp WHERE rp.role_id = 1 AND rp.permission_id = p.id);
